#!/usr/bin/env bash
# Generate include/wifi_networks.h from a plain-text credentials file.
#
# THIS SCRIPT NEVER PRINTS A PASSPHRASE. It reports counts and SSIDs only.
# SSIDs are broadcast over the air and are not secrets; passphrases are, and
# they go to the generated file and nowhere else.
#
# Input format, one network per line, in PRIORITY ORDER (first line tried first):
#
#   SSID:<network name>:<passphrase>
#
# The passphrase is everything after the SECOND colon, so a passphrase
# containing ':' is handled correctly. Blank lines and lines beginning '#'
# are ignored.
#
#   ./tools/gen-wifi-networks.sh ~/wifi.h
#
# The generated header is gitignored. Regenerate it whenever the file changes;
# credentials are compiled in, so the board must be reflashed to pick up edits.
set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="${1:-$HOME/wifi.h}"
OUT="$REPO/include/wifi_networks.h"

[ -f "$SRC" ] || { echo "no such file: $SRC" >&2; exit 1; }

awk -v out="$OUT" '
  function esc(s) { gsub(/\\/, "\\\\", s); gsub(/"/, "\\\"", s); return s }
  BEGIN {
    print "// GENERATED by tools/gen-wifi-networks.sh — do not edit, do not commit."  > out
    print "// Priority order: index 0 is tried first, ONE PER netPoll PASS."          > out
    print "// One association attempt per pass is a watchdog requirement, not a"      > out
    print "// preference: WiFi.begin() blocks up to 23 s against a 30 s heartbeat"    > out
    print "// tolerance. See the timing note above netPoll()."                        > out
    print ""                                                                          > out
    print "#pragma once"                                                              > out
    print ""                                                                          > out
    print "#include \"arduino_secrets.h\""                                            > out
    print ""                                                                          > out
    print "struct WifiNetwork {"                                                      > out
    print "  const char *ssid;"                                                       > out
    print "  const char *pass;"                                                       > out
    print "};"                                                                        > out
    print ""                                                                          > out
    print "static const WifiNetwork WIFI_NETWORKS[] = {"                              > out
    n = 0
  }
  /^[[:space:]]*#/ { next }
  /^[[:space:]]*$/ { next }
  /^[[:space:]]*SSID:/ {
    line = $0
    sub(/^[[:space:]]*SSID:/, "", line)
    c = index(line, ":")
    if (c == 0) { printf "  line %d: no passphrase separator, skipped\n", NR > "/dev/stderr"; next }
    name = substr(line, 1, c - 1)
    pw   = substr(line, c + 1)
    sub(/[[:space:]]+$/, "", pw)
    if (name == "" || pw == "") { printf "  line %d: empty ssid or passphrase, skipped\n", NR > "/dev/stderr"; next }
    printf "  { \"%s\", \"%s\" },\n", esc(name), esc(pw) > out
    names[n] = name
    n++
    next
  }
  { printf "  line %d: unrecognised, skipped\n", NR > "/dev/stderr" }
  END {
    print "};"                                                                        > out
    print ""                                                                          > out
    print "static const int WIFI_NETWORK_COUNT ="                                     > out
    print "  (int)(sizeof(WIFI_NETWORKS) / sizeof(WIFI_NETWORKS[0]));"                > out
    close(out)
    if (n == 0) { print "no networks parsed — refusing to write an empty table" > "/dev/stderr"; exit 1 }
    printf "wrote %d network(s), in priority order:\n", n
    for (i = 0; i < n; i++) printf "  %d. %s\n", i, names[i]
  }
' "$SRC"

echo "generated: ${OUT#"$REPO"/}  (passphrases not shown, and not logged)"
